def validate_protocol(p):
    probleme = []
    for feld in PFLICHT:
        wert = p.get(feld)
        if wert is None or str(wert).strip() == "":
            probleme.append(feld + "-fehlt")
    prereg = p.get("datum_prereg")
    haupt = p.get("datum_hauptlauf")
    if prereg and haupt and str(prereg).strip() and str(haupt).strip() and not (str(prereg) < str(haupt)):
        probleme.append("datum-reihenfolge")
    return sorted(probleme)

